import { describe, expect, it } from "vitest";

import {
  DEFAULT_STATE,
  hasActiveFilters,
  paramsToState,
  stateToParams,
  threadFromParams,
  threadToParams,
  type ThreadState,
} from "@/lib/search-state";

describe("threadToParams / threadFromParams", () => {
  it("round-trips a thread without a focused comment", () => {
    const thread: ThreadState = { rootId: 44123 };
    const params = threadToParams(thread, new URLSearchParams());

    expect(params.get("item")).toBe("44123");
    expect(params.get("c")).toBeNull();
    expect(threadFromParams(params)).toEqual({ rootId: 44123 });
  });

  it("round-trips a thread with a focused comment", () => {
    const thread: ThreadState = { rootId: 44123, focusId: 44567 };
    const params = threadToParams(thread, new URLSearchParams());

    expect(threadFromParams(params)).toEqual({ rootId: 44123, focusId: 44567 });
  });

  it("writes nothing when there is no thread open", () => {
    const params = threadToParams(null, new URLSearchParams());

    expect(params.toString()).toBe("");
  });

  it("reads no thread from params that have none", () => {
    expect(threadFromParams(new URLSearchParams("q=rust"))).toBeNull();
  });

  it("rejects a non-numeric or non-positive item id", () => {
    expect(threadFromParams(new URLSearchParams("item=abc"))).toBeNull();
    expect(threadFromParams(new URLSearchParams("item=0"))).toBeNull();
    expect(threadFromParams(new URLSearchParams("item=-5"))).toBeNull();
  });

  it("ignores a malformed focus id but keeps the thread", () => {
    expect(threadFromParams(new URLSearchParams("item=44123&c=abc"))).toEqual({
      rootId: 44123,
    });
  });

  it("coexists with search params without disturbing them", () => {
    const params = stateToParams({ ...DEFAULT_STATE, q: "rust", scope: "comments" });
    threadToParams({ rootId: 44123 }, params);

    expect(paramsToState(params).q).toBe("rust");
    expect(paramsToState(params).scope).toBe("comments");
    expect(threadFromParams(params)?.rootId).toBe(44123);
  });
});

describe("paramsToState", () => {
  it("keeps a points filter on the News tab", () => {
    expect(paramsToState(new URLSearchParams("points=100")).minPoints).toBe(100);
  });

  it("drops a points filter on the Comments tab, where comments have no score", () => {
    const state = paramsToState(new URLSearchParams("tab=comments&points=100"));

    expect(state.minPoints).toBe(0);
    expect(hasActiveFilters(state)).toBe(false);
  });
});

"use client";

import {
  keepPreviousData,
  useQuery,
  useQueryClient,
} from "@tanstack/react-query";
import { useEffect, useState } from "react";

import { searchOrFrontPage } from "@/lib/front-page";
import type { SearchRequest } from "@/lib/search-state";

export function useHNSearch(state: SearchRequest) {
  const queryClient = useQueryClient();
  const query = useQuery({
    queryKey: ["hn-search", state],
    queryFn: ({ signal }) => searchOrFrontPage(state, signal),
    placeholderData: keepPreviousData,
  });

  // Each committed search is a NEW query key, and TanStack does not
  // auto-cancel a stale key's in-flight request when the observer moves on —
  // so without this, superseded searches run to completion (and pile up when
  // the server is slow). Keyed on the SERIALIZED state (not the object ref,
  // which changes every keystroke before the debounce settles), the cleanup
  // fires once per committed search and aborts the one we're leaving.
  // keepPreviousData still shows the last good results while the next loads.
  const stateKey = JSON.stringify(state);
  useEffect(() => {
    return () => {
      queryClient.cancelQueries({
        queryKey: ["hn-search", JSON.parse(stateKey)],
        exact: true,
      });
    };
  }, [queryClient, stateKey]);

  return query;
}

/** Debounce fast-changing values (the query string) before they hit the
 *  network. 100ms keeps keystrokes snappy while still collapsing bursts;
 *  superseded requests abort, so a tight interval is cheap. */
export function useDebounced<T>(value: T, delayMs = 100): T {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delayMs);
    return () => clearTimeout(timer);
  }, [value, delayMs]);
  return debounced;
}

"use client";

import {
  MessagesSquare,
  Newspaper,
  Search,
  SlidersHorizontal,
  Sparkles,
  X,
} from "lucide-react";
import { useQueryClient } from "@tanstack/react-query";
import { useSearchParams } from "next/navigation";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";

import { Input } from "@/components/ui/input";
import { findCompletion } from "@/lib/autocomplete";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";
import { searchOrFrontPage } from "@/lib/front-page";
import { EMBEDDER, type HNHit } from "@/lib/meili";
import { useDebounced, useHNSearch } from "@/hooks/use-hn-search";
import { useOpenFacets } from "@/hooks/use-open-facets";
import {
  hasActiveFilters,
  paramsToState,
  stateToParams,
  threadFromParams,
  threadToParams,
  type Scope,
  type SearchState,
  type SortKey,
  type ThreadState,
  type ValueFacetDim,
} from "@/lib/search-state";
import { cn } from "@/lib/utils";

import { FacetRail } from "./facet-rail";
import { Results } from "./results";
import { ThreadView } from "./thread-view";

const SORT_TABS: { value: SortKey; label: string }[] = [
  { value: "relevance", label: "Relevance" },
  { value: "date", label: "Newest" },
  { value: "points", label: "Points" },
];

const SCOPE_TABS = [
  { value: "news", label: "News", icon: Newspaper },
  { value: "comments", label: "Comments", icon: MessagesSquare },
] as const;

// Domain doesn't exist on the Comments side, so a stored preference for it
// must not make us compute counts nothing will render.
const AVAILABLE_DIMS: Record<Scope, ValueFacetDim[]> = {
  news: ["domain", "author"],
  comments: ["author"],
};

export function SearchApp() {
  const searchParams = useSearchParams();
  const [state, setState] = useState<SearchState>(() =>
    paramsToState(new URLSearchParams(searchParams.toString())),
  );
  const [thread, setThread] = useState<ThreadState | null>(() =>
    threadFromParams(new URLSearchParams(searchParams.toString())),
  );
  // The already-loaded hit behind an open thread, so its header paints without
  // a fetch. Absent on deep links and after a back/forward navigation.
  const [threadSeed, setThreadSeed] = useState<HNHit | undefined>(undefined);
  // Opening or closing a thread is a navigation and pushes; every other state
  // change keeps rewriting the current entry, as the app has always done.
  const historyMode = useRef<"replace" | "push">("replace");
  const inputRef = useRef<HTMLInputElement>(null);

  // Every filter change resets pagination; explicit page changes override.
  // Touching any search control also leaves an open thread — no dead controls.
  const update = useCallback((patch: Partial<SearchState>) => {
    setState((prev) => ({ ...prev, page: 1, ...patch }));
    setThread(null);
    setThreadSeed(undefined);
  }, []);

  // Tags, domains and points only exist on the News side. Drop whatever
  // can't apply when switching tabs.
  const setScope = useCallback(
    (scope: Scope) => {
      setState((prev) => ({
        ...prev,
        scope,
        page: 1,
        tags: [],
        domains: [],
        minPoints: scope === "comments" ? 0 : prev.minPoints,
        sort:
          scope === "comments" && prev.sort === "points"
            ? "relevance"
            : prev.sort,
      }));
      setThread(null);
      setThreadSeed(undefined);
    },
    [],
  );

  useEffect(() => {
    const params = threadToParams(thread, stateToParams(state));
    const qs = params.toString();
    const url = qs ? `?${qs}` : window.location.pathname;
    if (historyMode.current === "push") window.history.pushState(null, "", url);
    else window.history.replaceState(null, "", url);
    historyMode.current = "replace";
  }, [state, thread]);

  // The app wrote history with replaceState only, so back did nothing. Now that
  // threads push entries, both kinds of state have to be rehydrated from the URL.
  useEffect(() => {
    const onPopState = () => {
      const params = new URLSearchParams(window.location.search);
      setState(paramsToState(params));
      setThread(threadFromParams(params));
      setThreadSeed(undefined);
    };
    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "/" && document.activeElement?.tagName !== "INPUT") {
        e.preventDefault();
        inputRef.current?.focus();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  // Expanding a facet section is a display change, not a filter change, so it
  // goes through this setter and never touches `state` — which also means it
  // can't reset pagination the way update() does.
  const [facetPrefs, toggleFacet] = useOpenFacets();

  // A section with active selections is force-expanded — its values have to
  // stay visible. Derived here rather than in useOpenFacets so it never gets
  // persisted as an explicit preference. Iterating AVAILABLE_DIMS (rather than
  // the preference set) also keeps the order stable, which matters because
  // this lands in the TanStack query key.
  const openFacets = useMemo(() => {
    const open = new Set(facetPrefs);
    if (state.domains.length) open.add("domain");
    if (state.authors.length) open.add("author");
    return AVAILABLE_DIMS[state.scope].filter((d) => open.has(d));
  }, [facetPrefs, state.domains, state.authors, state.scope]);

  const debouncedQ = useDebounced(state.q);
  const queryState = useMemo(
    () => ({ ...state, q: debouncedQ, openFacets }),
    [state, debouncedQ, openFacets],
  );
  const search = useHNSearch(queryState);

  // Warm a page's results on hover so clicking it paints instantly. The key
  // must match useHNSearch's exactly, so it's built from the same queryState.
  const queryClient = useQueryClient();
  const prefetchPage = useCallback(
    (page: number) => {
      const target = { ...queryState, page };
      queryClient.prefetchQuery({
        queryKey: ["hn-search", target],
        queryFn: ({ signal }) => searchOrFrontPage(target, signal),
        staleTime: 30_000,
      });
    },
    [queryClient, queryState],
  );

  // Ghost suffix completing the word being typed, accepted with Tab / →.
  // Long queries scroll inside the input and the overlay wouldn't track,
  // so stop suggesting before that point.
  const ghost = useMemo(() => {
    if (state.q.length > 40) return "";
    return findCompletion(state.q, search.data?.completionHits ?? []);
  }, [state.q, search.data]);

  const resetFilters = () =>
    update({
      tags: [],
      domains: [],
      authors: [],
      dateRange: "all",
      minPoints: 0,
    });

  const openThread = useCallback((next: ThreadState, seed?: HNHit) => {
    historyMode.current = "push";
    setThread(next);
    setThreadSeed(seed);
    window.scrollTo({ top: 0 });
  }, []);

  const closeThread = useCallback(() => {
    historyMode.current = "push";
    setThread(null);
    setThreadSeed(undefined);
  }, []);

  // A deep link can point at a comment; ThreadView resolves it upward and the
  // URL is corrected in place rather than pushing a second history entry.
  const replaceThread = useCallback((next: ThreadState) => {
    setThread(next);
    setThreadSeed(undefined);
  }, []);

  const activeFilterCount =
    state.tags.length +
    state.domains.length +
    state.authors.length +
    (state.dateRange !== "all" ? 1 : 0) +
    (state.minPoints > 0 ? 1 : 0);
  // Rendered twice: in the desktop rail and inside the mobile filter sheet.
  const facetRail = (
    <FacetRail
      state={state}
      facets={search.data?.facets}
      openFacets={openFacets}
      onToggleFacet={toggleFacet}
      onChange={update}
      onReset={resetFilters}
      showReset={hasActiveFilters(state)}
    />
  );
  const sortTabs = SORT_TABS.filter(
    (tab) => state.scope !== "comments" || tab.value !== "points",
  );

  return (
    <div className="flex min-h-dvh flex-col">
      <header className="border-b bg-card">
        <div className="mx-auto w-full max-w-6xl px-4 pt-5 pb-0 sm:px-6">
          <div className="flex items-baseline justify-between gap-4">
            <div className="flex items-baseline gap-2.5">
              {/* self-center against the title's line box (both 28px) instead
                  of a baseline + translate nudge, which sat visibly high. */}
              <span className="grid size-7 self-center place-items-center bg-primary font-mono text-lg font-semibold text-primary-foreground">
                H
              </span>
              <h1 className="text-xl font-semibold tracking-tight">
                HackerSearch
              </h1>
              <span className="hidden font-mono text-xs text-muted-foreground sm:inline">
                every story · every comment
              </span>
            </div>
            <div className="font-mono text-xs text-muted-foreground">
              <a
                href="https://www.meilisearch.com"
                className="hover:text-primary"
                target="_blank"
                rel="noreferrer"
              >
                meilisearch
              </a>
            </div>
          </div>

          <div className="relative mt-4 w-full max-w-xl">
            <Search className="pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              ref={inputRef}
              value={state.q}
              onChange={(e) => update({ q: e.target.value })}
              onKeyDown={(e) => {
                if (!ghost) return;
                const el = e.currentTarget;
                const caretAtEnd =
                  el.selectionStart === el.value.length &&
                  el.selectionEnd === el.value.length;
                if (
                  (e.key === "Tab" && !e.shiftKey) ||
                  (e.key === "ArrowRight" && caretAtEnd)
                ) {
                  e.preventDefault();
                  update({ q: state.q + ghost });
                }
              }}
              placeholder={
                state.scope === "comments"
                  ? "Search every HN comment…"
                  : "Search every HN story…"
              }
              className="h-11 rounded-none border bg-background pr-16 pl-9 font-mono text-sm shadow-none focus-visible:ring-0 focus-visible:border-primary md:text-sm"
              autoFocus
            />
            {ghost && (
              // Ghost completion overlay: an invisible copy of the query
              // keeps the suffix aligned with the caret (monospace font).
              <div
                aria-hidden
                className="pointer-events-none absolute inset-0 flex items-center overflow-hidden border border-transparent pr-16 pl-9 font-mono text-sm whitespace-pre"
              >
                <span className="invisible">{state.q}</span>
                <span className="text-muted-foreground/70">{ghost}</span>
              </div>
            )}
            {state.q ? (
              <button
                onClick={() => update({ q: "" })}
                className="absolute top-1/2 right-3 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                aria-label="Clear search"
              >
                <X className="size-4" />
              </button>
            ) : (
              <kbd className="pointer-events-none absolute top-1/2 right-3 -translate-y-1/2 border bg-muted px-1.5 font-mono text-[10px] text-muted-foreground">
                /
              </kbd>
            )}
          </div>

          <div className="mt-3 flex items-end justify-between gap-2">
            <nav className="flex gap-0">
              {SCOPE_TABS.map((tab) => (
                <button
                  key={tab.value}
                  onClick={() => setScope(tab.value)}
                  className={cn(
                    "flex items-center gap-2 border-x border-t border-transparent px-3 py-2 text-sm font-medium transition-colors sm:px-4",
                    state.scope === tab.value
                      ? "border-border bg-background text-primary"
                      : "text-muted-foreground hover:text-foreground",
                  )}
                >
                  <tab.icon className="size-4 max-sm:hidden" />
                  {tab.label}
                </button>
              ))}
            </nav>

            <div className="flex items-center gap-2 pb-1 sm:pb-0">
              {EMBEDDER && (
                <button
                  onClick={() => update({ semantic: !state.semantic })}
                  title="Blend keyword and vector search (embeds titles + crawled article content)"
                  className={cn(
                    "flex items-center gap-1.5 border px-3 py-1.5 font-mono text-xs transition-colors",
                    state.semantic
                      ? "border-primary bg-primary text-primary-foreground"
                      : "bg-card text-muted-foreground hover:border-primary hover:text-primary",
                  )}
                >
                  <Sparkles className="size-3.5" />
                  <span className="hidden sm:inline">semantic</span>
                </button>
              )}

              {/* Mobile: facets live in a sheet; sort collapses to a select. */}
              <Sheet>
                <SheetTrigger asChild>
                  <button
                    className="relative flex items-center gap-1.5 border bg-card px-2.5 py-1.5 font-mono text-xs text-muted-foreground transition-colors hover:border-primary hover:text-primary md:hidden"
                    aria-label="Open filters"
                  >
                    <SlidersHorizontal className="size-3.5" />
                    <span className="max-sm:sr-only">filters</span>
                    {activeFilterCount > 0 && (
                      <span className="grid size-4 place-items-center bg-primary text-[10px] font-semibold text-primary-foreground">
                        {activeFilterCount}
                      </span>
                    )}
                  </button>
                </SheetTrigger>
                <SheetContent
                  side="left"
                  className="w-72 overflow-y-auto bg-background"
                >
                  <SheetHeader className="pb-0">
                    <SheetTitle className="font-mono text-xs font-semibold tracking-[0.2em] text-muted-foreground uppercase">
                      Filters
                    </SheetTitle>
                  </SheetHeader>
                  <div className="px-4 pb-8">{facetRail}</div>
                </SheetContent>
              </Sheet>

              <label className="sm:hidden">
                <span className="sr-only">Sort results</span>
                <select
                  value={state.sort}
                  onChange={(e) =>
                    update({ sort: e.target.value as SortKey })
                  }
                  className="border bg-card px-2 py-1.5 font-mono text-xs text-muted-foreground"
                >
                  {sortTabs.map((tab) => (
                    <option key={tab.value} value={tab.value}>
                      {tab.label}
                    </option>
                  ))}
                </select>
              </label>

              <nav className="hidden items-end gap-0 self-end sm:flex">
                {sortTabs.map((tab) => (
                  <button
                    key={tab.value}
                    onClick={() => update({ sort: tab.value })}
                    className={cn(
                      "border-x border-t border-transparent px-4 py-2 font-mono text-xs transition-colors",
                      state.sort === tab.value
                        ? "border-border bg-background text-primary"
                        : "text-muted-foreground hover:text-foreground",
                    )}
                  >
                    {tab.label}
                  </button>
                ))}
              </nav>
            </div>
          </div>
        </div>
      </header>

      <main className="mx-auto flex w-full max-w-6xl flex-1 gap-8 px-4 py-6 sm:px-6">
        <aside className="hidden w-56 shrink-0 md:block">
          <div className="sticky top-6">{facetRail}</div>
        </aside>

        <section className="min-w-0 flex-1">
          {thread ? (
            <ThreadView
              rootId={thread.rootId}
              focusId={thread.focusId}
              seed={threadSeed}
              onClose={closeThread}
              onResolveRoot={replaceThread}
            />
          ) : (
            <Results
              search={search}
              state={state}
              onPage={(page) => {
                update({ page });
                window.scrollTo({ top: 0 });
              }}
              onPrefetchPage={prefetchPage}
              onState={update}
              onOpenThread={openThread}
            />
          )}
        </section>
      </main>

      <footer className="border-t">
        <div className="mx-auto flex w-full max-w-6xl items-center justify-between px-4 py-3 font-mono text-[11px] text-muted-foreground sm:px-6">
          <span>
            data ·{" "}
            <a
              href="https://github.com/HackerNews/API"
              className="hover:text-primary"
              target="_blank"
              rel="noreferrer"
            >
              HN Firebase API
            </a>
          </span>
          <span>
            search ·{" "}
            <a
              href="https://www.meilisearch.com"
              className="hover:text-primary"
              target="_blank"
              rel="noreferrer"
            >
              Meilisearch
            </a>
          </span>
        </div>
      </footer>
    </div>
  );
}

export const TAG_OPTIONS = [
  { value: "story", label: "Stories" },
  { value: "ask_hn", label: "Ask HN" },
  { value: "show_hn", label: "Show HN" },
  { value: "launch_hn", label: "Launch HN" },
  { value: "job", label: "Jobs" },
  { value: "poll", label: "Polls" },
] as const;

export const DATE_RANGES = [
  { value: "all", label: "All time", seconds: 0 },
  { value: "24h", label: "Past 24 hours", seconds: 86_400 },
  { value: "week", label: "Past week", seconds: 7 * 86_400 },
  { value: "month", label: "Past month", seconds: 30 * 86_400 },
  { value: "year", label: "Past year", seconds: 365 * 86_400 },
] as const;

export const POINTS_OPTIONS = [0, 10, 50, 100, 500] as const;

export type DateRange = (typeof DATE_RANGES)[number]["value"];
export type SortKey = "relevance" | "date" | "points";
export type Scope = "news" | "comments";

/** The two high-cardinality facets whose rail sections collapse. */
export type ValueFacetDim = "domain" | "author";

export interface SearchState {
  scope: Scope;
  semantic: boolean;
  q: string;
  tags: string[];
  domains: string[];
  authors: string[];
  dateRange: DateRange;
  minPoints: number;
  sort: SortKey;
  page: number;
}

/**
 * What actually goes to Meilisearch: the shareable state plus which
 * high-cardinality facets to compute counts for. Openness shapes the request
 * but is a local preference rather than shareable state, so it lives here and
 * never reaches stateToParams / paramsToState / hasActiveFilters.
 */
export interface SearchRequest extends SearchState {
  openFacets: ValueFacetDim[];
}

export const DEFAULT_STATE: SearchState = {
  scope: "news",
  semantic: false,
  q: "",
  tags: [],
  domains: [],
  authors: [],
  dateRange: "all",
  minPoints: 0,
  sort: "relevance",
  page: 1,
};

export function hasActiveFilters(s: SearchState): boolean {
  return (
    s.tags.length > 0 ||
    s.domains.length > 0 ||
    s.authors.length > 0 ||
    s.dateRange !== "all" ||
    s.minPoints > 0
  );
}

export function stateToParams(s: SearchState): URLSearchParams {
  const p = new URLSearchParams();
  if (s.scope !== "news") p.set("tab", s.scope);
  if (s.semantic) p.set("sem", "1");
  if (s.q) p.set("q", s.q);
  if (s.tags.length) p.set("tags", s.tags.join(","));
  if (s.domains.length) p.set("domains", s.domains.join(","));
  if (s.authors.length) p.set("authors", s.authors.join(","));
  if (s.dateRange !== "all") p.set("date", s.dateRange);
  if (s.minPoints > 0) p.set("points", String(s.minPoints));
  if (s.sort !== "relevance") p.set("sort", s.sort);
  if (s.page > 1) p.set("page", String(s.page));
  return p;
}

export function paramsToState(p: URLSearchParams): SearchState {
  const list = (key: string) =>
    p.get(key)?.split(",").filter(Boolean) ?? [];
  const date = p.get("date");
  const sort = p.get("sort");
  const scope: Scope = p.get("tab") === "comments" ? "comments" : "news";
  return {
    scope,
    semantic: p.get("sem") === "1",
    q: p.get("q") ?? "",
    tags: list("tags"),
    domains: list("domains"),
    authors: list("authors"),
    dateRange: DATE_RANGES.some((d) => d.value === date)
      ? (date as DateRange)
      : "all",
    // Comments have no points; a hand-edited link must not count as a filter.
    minPoints:
      scope === "comments" ? 0 : Math.max(0, Number(p.get("points")) || 0),
    sort: sort === "date" || sort === "points" ? sort : "relevance",
    page: Math.max(1, Number(p.get("page")) || 1),
  };
}

/**
 * Which thread is open, if any. Deliberately NOT part of SearchState: that
 * object is the TanStack query key for searches, and folding the thread into
 * it would refetch every result each time a thread opens or closes.
 */
export interface ThreadState {
  rootId: number;
  focusId?: number;
}

const positiveId = (raw: string | null): number | null => {
  const value = Number(raw);
  return Number.isInteger(value) && value > 0 ? value : null;
};

export function threadToParams(
  thread: ThreadState | null,
  params: URLSearchParams,
): URLSearchParams {
  if (!thread) return params;
  params.set("item", String(thread.rootId));
  if (thread.focusId != null) params.set("c", String(thread.focusId));
  return params;
}

export function threadFromParams(params: URLSearchParams): ThreadState | null {
  const rootId = positiveId(params.get("item"));
  if (rootId === null) return null;
  const focusId = positiveId(params.get("c"));
  return focusId === null ? { rootId } : { rootId, focusId };
}

